// [English pattern, [French, Chinese, Bangla]]; a translation can be a function of the matched parts
// a part of a matched sentence that has its own translation ("today at 3 PM" inside "Yours · today at 3 PM")
const i18nPart = (w) => i18nLookup(w) ?? w;
const I18N_PATTERN_TABLE = [
  [/^Your trips \((\d+)\)$/, ["Vos voyages ($1)", "我的行程（$1）", "আপনার ভ্রমণ ($1)"]],
  [/^Trip idea: (.+), (\d+) days?$/, ["Idée de voyage : $1, $2 jours", "旅行灵感：$1，$2 天", "ভ্রমণের আইডিয়া: $1, $2 দিন"]],
  [/^Your trip: (.+), (\d+) days? · (.+) driving$/, ["Votre voyage : $1, $2 jours · $3 de conduite", "我的行程：$1，$2 天 · 驾驶 $3", "আপনার ভ্রমণ: $1, $2 দিন · $3 ড্রাইভিং"]],
  [/^Ready to go: (.+), (\d+) days? · (.+) driving$/, ["Prêt à partir : $1, $2 jours · $3 de conduite", "即刻出发：$1，$2 天 · 驾驶 $3", "যাত্রার জন্য প্রস্তুত: $1, $2 দিন · $3 ড্রাইভিং"]],
  [/^(\d+) days? · ([\d,]+ (?:mi|km)) · (.+) driving$/, ["$1 jours · $2 · $3 de conduite", "$1 天 · $2 · 驾驶 $3", "$1 দিন · $2 · $3 ড্রাইভিং"]],
  [/^(\d+) days? · (\S+(?: \S+)?) driving$/, ["$1 jours · $2 de conduite", "$1 天 · 驾驶 $2", "$1 দিন · $2 ড্রাইভিং"]],
  [/^(\d+) days? · (.+) to (.+)$/, ["$1 jours · de $2 à $3", "$1 天 · $2 至 $3", "$1 দিন · $2 থেকে $3"]],
  [/^(\d+) of yours and (\d+) ready to go\. Open one as it is, or start from it and make it yours\.$/, ["$1 à vous et $2 tout prêts. Ouvrez-en un tel quel, ou partez de lui pour en faire le vôtre.", "您的 $1 个，现成 $2 个。直接打开，或以它为起点改成您自己的。", "আপনার $1টি এবং তৈরি $2টি। যেমন আছে তেমন খুলুন, অথবা সেখান থেকে শুরু করে নিজের মতো করে নিন।"]],
  [/^([\d.]+) hours$/, ["$1 heures", "$1 小时", "$1 ঘণ্টা"]],
  [/^today at (.+)$/, ["aujourd'hui à $1", "今天 $1", "আজ $1"]],
  [/^(\d+) days ago$/, ["il y a $1 jours", "$1 天前", "$1 দিন আগে"]],
  [/^Yours · (.+)$/, [(m, a) => `À vous · ${i18nPart(a)}`, (m, a) => `我的 · ${i18nPart(a)}`, (m, a) => `আপনার · ${i18nPart(a)}`]],
  [/^Your trip · edited (.+?) · (.+)$/, [(m, a, b) => `Votre voyage · modifié ${i18nPart(a)} · ${i18nPart(b)}`, (m, a, b) => `我的行程 · ${i18nPart(a)}编辑 · ${i18nPart(b)}`, (m, a, b) => `আপনার ভ্রমণ · সম্পাদিত ${i18nPart(a)} · ${i18nPart(b)}`]],
  [/^Night in (.+?) · (.+)$/, ["Nuit à $1 · $2", "夜宿 $1 · $2", "রাত $1-এ · $2"]],
  [/^Day (\d+)$/, ["Jour $1", "第 $1 天", "দিন $1"]],
  [/^Day (\d+), (.+)$/, ["Jour $1, $2", "第 $1 天，$2", "দিন $1, $2"]],
  [/^Open day (\d+) in (Google|Apple) Maps$/, ["Ouvrir le jour $1 dans $2 Maps", "在 $2 地图中打开第 $1 天", "$2 Maps-এ দিন $1 খুলুন"]],
  [/^\+(.+) vs fastest$/, ["+$1 par rapport au plus rapide", "比最快路线多 $1", "দ্রুততম পথের চেয়ে +$1"]],
  [/^([\d,]+) (mi|km) unpaved$/, ["$1 $2 non revêtus", "$1 $2 未铺装", "$1 $2 কাঁচা রাস্তা"]],
  [/^(\d+) featured roads?$/, ["$1 routes phares", "$1 条精选公路", "$1টি বিশেষ রাস্তা"]],
  [/^(\d+)% featured roads$/, ["$1 % de routes phares", "精选公路占 $1%", "$1% বিশেষ রাস্তা"]],
  [/^leave (.+) · max ([\d.]+) h a day$/, ["départ $1 · max $2 h par jour", "$1 出发 · 每天最多 $2 小时", "রওনা $1 · দিনে সর্বোচ্চ $2 ঘণ্টা"]],
  [/^about (\S+) to (\S+)$/, ["environ $1 à $2", "约 $1 至 $2", "প্রায় $1 থেকে $2"]],
  [/^Leave (.+)$/, ["Départ de $1", "从 $1 出发", "$1 থেকে রওনা"]],
  [/^Arrive (.+)$/, ["Arrivée à $1", "抵达 $1", "$1-এ পৌঁছানো"]],
  [/^(Landmark|Viewpoint|Photo spot|Hot spring|Town|Waterfall|Park|Hike|Food) · stop (.+?)(?: · (.+) off route)?$/, [
    (m, a, b, c) => `${i18nPart(a)} · arrêt ${b}${c ? ` · à ${c} de la route` : ""}`,
    (m, a, b, c) => `${i18nPart(a)} · 停留 ${b}${c ? ` · 偏离路线 ${c}` : ""}`,
    (m, a, b, c) => `${i18nPart(a)} · বিরতি ${b}${c ? ` · পথ থেকে ${c} দূরে` : ""}`,
  ]],
  [/^Featured road · (.+)$/, ["Route phare · $1", "精选公路 · $1", "বিশেষ রাস্তা · $1"]],
  [/^(.+) driving \+ (.+) of stops$/, ["$1 de conduite + $2 d'arrêts", "驾驶 $1 + 停留 $2", "$1 ড্রাইভিং + $2 বিরতি"]],
  [/^from (.+) to (.+) · (.+) on this route$/, ["de $1 à $2 · $3 sur ce trajet", "$1 至 $2 · 本路线 $3", "$1 থেকে $2 · এই পথে $3"]],
  [/^([\d,]+ (?:mi|km)) off route$/, ["à $1 de la route", "偏离路线 $1", "পথ থেকে $1 দূরে"]],
  [/^(\d+) hairpins?$/, ["$1 épingles", "$1 个发夹弯", "$1টি হেয়ারপিন বাঁক"]],
  [/^([\d,]+ (?:ft|m)) climb$/, ["$1 de montée", "爬升 $1", "$1 চড়াই"]],
  [/^top ([\d,]+ (?:ft|m))$/, ["sommet $1", "最高 $1", "সর্বোচ্চ $1"]],
  [/^steepest km (\d+)%$/, ["km le plus raide $1 %", "最陡一公里 $1%", "সবচেয়ে খাড়া কিমি $1%"]],
  [/^(\d+)° of turning per km$/, ["$1° de virage par km", "每公里转向 $1°", "প্রতি কিমিতে $1° বাঁক"]],
  [/^The day's drive, (.+) to (.+)$/, ["Le trajet du jour, de $1 à $2", "当天路程，海拔 $1 至 $2", "দিনের যাত্রা, $1 থেকে $2"]],
  [/^Photos of (.+)$/, ["Photos de $1", "$1 的照片", "$1-এর ছবি"]],
  [/^Fastest (.+)$/, ["Plus rapide $1", "最快 $1", "দ্রুততম $1"]],
  [/^([\d,]+ (?:mi|km)), (.+) longer$/, ["$1, $2 de plus", "$1，多 $2", "$1, $2 বেশি"]],
  [/^via (.+)$/, ["via $1", "途经 $1", "$1 হয়ে"]],
  [/^Switch to fastest route, (.+)$/, ["Passer à l'itinéraire le plus rapide, $1", "切换到最快路线，$1", "দ্রুততম পথে যান, $1"]],
  [/^Change: “skip (.+)”$/, ["Modifier : « éviter $1 »", "修改：“跳过 $1”", "বদলান: “$1 বাদ দিন”"]],
  [/^Stay overnight at (.+)$/, ["Passer la nuit à $1", "在 $1 过夜", "$1-এ রাত কাটান"]],
  [/^Overnight at (.+)\. Click to keep driving instead$/, ["Nuit à $1. Cliquez pour continuer la route", "在 $1 过夜。点击改为继续行驶", "$1-এ রাত্রিযাপন। এর বদলে চালিয়ে যেতে ক্লিক করুন"]],
  [/^Move (.+) up$/, ["Monter $1", "上移 $1", "$1 উপরে সরান"]],
  [/^Move (.+) down$/, ["Descendre $1", "下移 $1", "$1 নিচে সরান"]],
  [/^Remove (.+)$/, ["Retirer $1", "移除 $1", "$1 সরান"]],
  [/^fuel (\S+)(?: · (\d+) nights? (\S+) to (\S+))?$/, [
    (m, f, n, lo, hi) => `carburant ${f}${n ? ` · ${n} nuits ${lo} à ${hi}` : ""}`,
    (m, f, n, lo, hi) => `油费 ${f}${n ? ` · ${n} 晚 ${lo} 至 ${hi}` : ""}`,
    (m, f, n, lo, hi) => `জ্বালানি ${f}${n ? ` · ${n} রাত ${lo} থেকে ${hi}` : ""}`,
  ]],
  [/^charging (\S+)(?: · (\d+) nights? (\S+) to (\S+))?$/, [
    (m, f, n, lo, hi) => `recharge ${f}${n ? ` · ${n} nuits ${lo} à ${hi}` : ""}`,
    (m, f, n, lo, hi) => `充电费 ${f}${n ? ` · ${n} 晚 ${lo} 至 ${hi}` : ""}`,
    (m, f, n, lo, hi) => `চার্জিং ${f}${n ? ` · ${n} রাত ${lo} থেকে ${hi}` : ""}`,
  ]],
  [/^(\S*\d\S*) to (\S*\d\S*)$/, ["$1 à $2", "$1 至 $2", "$1 থেকে $2"]],
  [/^([A-Z]{3}) a (gallon|litre|kWh)$/, [(m, c, u) => `${c} par ${{ gallon: "gallon", litre: "litre", kWh: "kWh" }[u]}`, (m, c, u) => `${c}/${{ gallon: "加仑", litre: "升", kWh: "千瓦时" }[u]}`, (m, c, u) => `প্রতি ${{ gallon: "গ্যালন", litre: "লিটার", kWh: "কিলোওয়াট-ঘণ্টা" }[u]} ${c}`]],
  [/^(\$+) · (\S+) to (\S+)$/, ["$1 · $2 à $3", "$1 · $2 至 $3", "$1 · $2 থেকে $3"]],
  [/^Saved \((.+)\)\. Paste a new key to replace it$/, ["Enregistrée ($1). Collez une nouvelle clé pour la remplacer", "已保存（$1）。粘贴新密钥以替换", "সংরক্ষিত ($1)। বদলাতে নতুন কী পেস্ট করুন"]],
  [/^(\d+) roads? on this trip closes? for part of the year: (.+)\.$/, ["$1 route(s) de ce voyage ferment une partie de l'année : $2.", "本次行程有 $1 条路一年中会封闭一段时间：$2。", "এই ভ্রমণের $1টি রাস্তা বছরের কিছু সময় বন্ধ থাকে: $2।"]],
  [/^from (.+) to (.+) · Days? (.+)$/, ["de $1 à $2 · Jour $3", "$1 至 $2 · 第 $3 天", "$1 থেকে $2 · দিন $3"]],
  [/^Ask for a change: “skip (.+?)”, “add a night in (.+?)”, “more switchbacks, fewer highways”$/, ["Demandez une modification : « éviter $1 », « une nuit de plus à $2 », « plus de lacets, moins d'autoroutes »", "提出修改：“跳过 $1”“在 $2 多住一晚”“多些盘山路，少些高速”", "পরিবর্তন চান: “$1 বাদ দিন”, “$2-এ এক রাত যোগ করুন”, “আরও বাঁক, কম হাইওয়ে”"]],
  [/^Ask about the trip: “where should we eat in (.+?)\?”, “is day (\d+) too much with kids\?”, “where's the last fuel before (.+?)\?”$/, ["Posez une question : « où manger à $1 ? », « le jour $2 est-il trop long avec des enfants ? », « où est le dernier plein avant $3 ? »", "询问行程：“在 $1 该去哪吃？”“第 $2 天带孩子会不会太累？”“$3 之前最后的加油站在哪？”", "ভ্রমণ নিয়ে প্রশ্ন করুন: “$1-এ কোথায় খাব?”, “বাচ্চাদের নিয়ে দিন $2 কি বেশি?”, “$3-এর আগে শেষ জ্বালানি কোথায়?”"]],
  [/^([\d,]+ (?:mi|km)) to go · arrive about (.+?) · sunset (.+)$/, ["encore $1 · arrivée vers $2 · coucher du soleil $3", "还剩 $1 · 约 $2 到达 · 日落 $3", "আর $1 বাকি · প্রায় $2-এ পৌঁছানো · সূর্যাস্ত $3"]],
  [/^([\d,]+ (?:mi|km)) · (\d+) min stop$/, ["$1 · arrêt $2 min", "$1 · 停留 $2 分钟", "$1 · $2 মিনিট বিরতি"]],
  [/^Send day (\d+) to your phone$/, ["Envoyer le jour $1 au téléphone", "把第 $1 天发送到手机", "দিন $1 আপনার ফোনে পাঠান"]],
  [/^Usually open (\w+ \d+) to (\w+ \d+)\.$/, ["Ouvert en général du $1 au $2.", "通常 $1 至 $2 开放。", "সাধারণত $1 থেকে $2 খোলা থাকে।"]],
  [/^Today: (\d+) requests? to Gemini(.*)$/, ["Aujourd'hui : $1 requêtes à Gemini$2", "今天：向 Gemini 发出 $1 次请求$2", "আজ: Gemini-তে $1টি অনুরোধ$2"]],
];

// spread the table into I18N (i18n.js) per language
["fr", "zh", "bn"].forEach((lang, i) => {
  I18N[lang] = {};
  for (const [en, langs] of Object.entries(I18N_TABLE)) if (langs[i]) I18N[lang][en] = langs[i];
  I18N_PATTERNS[lang] = I18N_PATTERN_TABLE.map(([re, langs]) => [re, langs[i]]).filter(([, x]) => x);
});
